using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DiceCatalogerConditionToBeSelected", menuName = "Data/BattleSceneSetups/Events/DiceCatalogerConditionToBeSelected", order = 0)]
public class DiceCatalogerConditionToBeSelected : CustomEventSetupConditionToBeSelected
{
	[SerializeField]
	private GainByDieTierRewardEventAction[] GainByDieTierRewardEventActions;

	public override bool CheckConditionToBeSelected()
	{
		for (int i = 0; i < GainByDieTierRewardEventActions.Length; i++)
		{
			if (GainByDieTierRewardEventActions[i].GetMultiplier() >= 1)
			{
				return true;
			}
		}
		return false;
	}
}
